"""Regenerates docs/CursedBrokerAudit.md from Broker/CurseRules.cs and Broker/CursePenalties.cs.
Run from the repo root: python tools/gen_curse_audit.py"""
import re

rules = open('CursedAppleCuriosities/Broker/CurseRules.cs', encoding='utf-8').read()
pens = open('CursedAppleCuriosities/Broker/CursePenalties.cs', encoding='utf-8').read()

out = [
    "# Cursed Broker — item audit", "",
    "Generated by `tools/gen_curse_audit.py` from `CursedAppleCuriosities/Broker/CurseRules.cs` and `CursePenalties.cs`. "
    "Edit those, then regenerate.", "",
    "## How a curse buffs an item", "",
    "A curse is on the item, like a void item's \"corrupts all X\": every copy you hold or pick up later is cursed. "
    "Cursed copies count as **copies × Mult + Add** in the game's *effective* stack count "
    "(`Inventory.UpdateEffectiveItemStacks`), which is what every item reads, so the item's own stacking delivers the buff.", "",
    "- **×2**: linear per-stack items (damage, duration, charges): exactly double.",
    "- **×2 +1**: items whose first copy is worth more than later ones (e.g. Harvester's 8 (+4) heal: 1 copy → 3 = 16, double), "
    "or hyperbolic ones that need extra copies to reach about double.",
    "- **×3**: items where stacking only scales a secondary part (Ukulele targets/range, Warbanner radius) or is steeply "
    "hyperbolic (Lucky Shot, Inhibitor, Healing Tempo).",
    "- **Custom**: Dio's Best Friend and Pluripotent Larva keep their count; each copy revives twice instead.",
    "- **Not listed** (other mods' items): ×2, described as \"every per-stack effect doubled\".", "",
    "Eligible: White, Green, Red, Boss (yellow), and Void White/Green/Red/Boss. Excluded: hidden, unremovable, Scrap, "
    "world-unique, consumed-on-use items (Power Elixir), Regenerating Scrap, Ominous Loan Note, the Alloyed Collective power "
    "items and Junk. Lunar, Hex, Page and Food tiers are never offered. Later-DLC rows only apply if the item's runtime tier is "
    "eligible.", "",
    "## Items", "", "| Item (internal name) | Count | Improvement |", "|---|---|---|",
]
for line in rules.splitlines():
    m = re.match(r'\s*// ── (.+?) ─', line)
    if m:
        out.append(f"| **{m.group(1)}** | | |")
        continue
    m = re.match(r'\s*\[(?:"([^"]+)"|(\w+))\]\s*=\s*new CurseRule\((\d+), (\d+), "([^"]+)"\)', line)
    if m:
        name = m.group(1) or m.group(2)
        mult, add = int(m.group(3)), int(m.group(4))
        cnt = 'custom' if mult == 1 and add == 0 else f"×{mult}" + (f" +{add}" if add else "")
        out.append(f"| `{name}` | {cnt} | {m.group(5)} |")

out += [
    "", "## Penalty pool", "",
    "One penalty per curse, rolled per item the first time a player sees that item at a broker (kept for that broker, so "
    "reopening can't reroll). Whites roll the lower half of each range, greens the lower 70%, Red/Boss/Void Red the upper 70%. "
    "Penalties of the same kind stack multiplicatively (reductions) or additively (increases). They last the whole run, "
    "even if the item is lost.", "",
    "| Penalty | Range | Effect |", "|---|---|---|",
]
for m in re.finditer(r'new Def\(CursePenalty\.(\w+),\s*([\d.]+)f,\s*([\d.]+)f,\s*v => \$?"([^"]+)"\)', pens):
    k, a, b, t = m.groups()
    a, b = float(a), float(b)
    rng = f"{a:g}–{b:g}" if k == 'Armor' else ("fixed" if a == b else f"{a*100:g}–{b*100:g}%")
    t = re.sub(r'\{Pct\(v\)\}|\{Mathf\.RoundToInt\(v\)\}', 'N', t)
    out.append(f"| {k} | {rng} | {t} |")

open('docs/CursedBrokerAudit.md', 'w', encoding='utf-8').write("\n".join(out) + "\n")
print(f"{sum(1 for l in out if l.startswith('| `'))} items")
